//! 🎟️ Canonical owned byte calls stay inside their real instance through input, output and paid retirement.
use super::*;
use semio_framework_job::{StepContext,OriginalTurnFailure};
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_actor::OriginalGuestExecutionBudget;
fn unsupported()->OriginalTurnFailure{ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original unit calls require the actual owned backend and its owned instance").into()}
impl GuestRuntimes{
 /// 🎟️ Settles cleanup mode on the original call before the caller issues VM execution credit.
 pub fn prepare_original_retirement_step(&self,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};runtime.prepare_original_call_retirement_step(state,cx)}
 /// 🎯️ Fixed scalar arguments stay inline in the same genuine Source-owned instance.
 pub fn begin_original_scalar_step(&self,instance:&mut GuestInstance,export:OwnedSemioExport,arguments:&[OriginalCoreValue],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.begin_original_call_step(state,export,arguments,cx)}
 pub fn advance_original_scalar_step(&self,instance:&mut GuestInstance,execution:Option<OriginalGuestExecutionBudget>,cx:&mut StepContext<'_>)->Result<OwnedOriginalCallProgress,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.advance_original_call_step(state,execution,cx)}
 pub fn advance_original_scalar_step_receiving(&self,instance:&mut GuestInstance,execution:Option<OriginalGuestExecutionBudget>,receiver:&mut dyn OriginalOperationReceiving,cx:&mut StepContext<'_>)->Result<OwnedOriginalCallProgress,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.advance_original_call_step_receiving(state,execution,receiver,cx)}
 pub fn take_original_scalar_into_step(&self,instance:&mut GuestInstance,out:&mut Option<OwnedOriginalCallResult>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};runtime.take_original_call_result_into_step(state,out,cx)}
 pub fn with_original_scalar_bytes(&self,instance:&GuestInstance,pointer:u32,length:usize,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<(),OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};runtime.with_original_memory_bytes(state,pointer,length,cx,receive)}
 /// 📖️ Borrows the actual frozen header with its runtime-derived export and original Source fence.
 pub fn with_original_scalar_header(&self,instance:&GuestInstance,cx:&mut StepContext<'_>,receive:impl FnOnce(OwnedSemioExport,&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};runtime.with_original_scalar_header(state,cx,receive)}
 /// 🪙️ Borrows escrow only from the actual still-frozen scalar result.
 pub fn with_original_scalar_escrow(&self,instance:&GuestInstance,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};runtime.with_original_scalar_escrow(state,cx,receive)}
 /// 🪪️ Borrows the actual frozen export identity through the owned backend Source fence.
 pub fn original_scalar_export(&self,instance:&GuestInstance,cx:&StepContext<'_>)->Result<Option<OwnedSemioExport>,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};runtime.original_call_export(state,cx)}
 /// 🏷️ Borrows only an actual frozen ActorInput unit identity.
 pub fn original_unit_export(&self,instance:&GuestInstance,cx:&StepContext<'_>)->Result<Option<OwnedSemioExport>,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};runtime.owned_original_unit_export(state,cx)}
 pub fn original_scalar_requires_execution(&self,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{let(Self::Owned(_),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};Ok(state.original_call_requires_execution())}
 pub fn original_scalar_is_pending(&self,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{let(Self::Owned(_),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};Ok(state.original_call_is_pending())}
 pub fn close_original_scalar_step(&self,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};runtime.close_original_call_step(state,cx)}
 /// 🌱️ Transfers only an already Source-controlled donor into the same instance's owned frontier.
 pub fn begin_original_unit_step(&self,instance:&mut GuestInstance,donor:&mut Option<Vec<u8>>,budget:semio_framework_actor::OriginalJobBudget,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.begin_owned_original_unit_call_step(state,donor,budget,cx)}
 pub fn repeat_original_unit_step(&self,instance:&mut GuestInstance,budget:semio_framework_actor::OriginalJobBudget,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.repeat_owned_original_unit_call_step(state,budget,cx)}
 pub fn original_unit_waiting_for_budget(&self,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{let(Self::Owned(_),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};Ok(state.original_unit_waiting_for_budget())}
 /// 🔄️ Preserves the actual whole progress owner and execution receipt for its external Source recipient.
 pub fn advance_original_unit_step(&self,instance:&mut GuestInstance,execution:Option<OriginalGuestExecutionBudget>,cx:&mut StepContext<'_>)->Result<OwnedOriginalCallProgress,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};state.bind_original_clock(cx)?;runtime.advance_owned_original_unit_call_step(state,execution,cx)}
 /// 👁️ Output is borrowed while the actual instance memory stays frozen by its retained frontier.
 pub fn with_original_unit_output(&self,instance:&GuestInstance,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};let Some(bytes)=runtime.owned_original_unit_output(state,cx)?else{return Ok(false)};receive(bytes,cx)?;Ok(true)}
 /// 🪙️ Borrows only the escrow extent named by the still-frozen actual unit header.
 pub fn with_original_unit_escrow(&self,instance:&GuestInstance,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};let Some(bytes)=runtime.owned_original_unit_escrow(state,cx)?else{return Ok(false)};receive(bytes,cx)?;Ok(true)}
 /// ✅️ Acknowledges the exact borrowed output before the actual guest handback export can execute.
 pub fn acknowledge_original_unit_step(&self,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};runtime.acknowledge_owned_original_unit_call_step(state,cx)}
 /// 🧹️ The same source retires partial Core state and the already controlled donor backing.
 pub fn close_original_unit_step(&self,instance:&mut GuestInstance,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let(Self::Owned(runtime),GuestInstanceState::Owned(state))=(self,&mut instance.state)else{return Err(unsupported())};runtime.close_owned_original_unit_call_step(state,cx)}
 pub fn original_unit_requires_execution(&self,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{let(Self::Owned(_),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};Ok(state.original_unit_requires_execution())}
 pub fn original_unit_is_pending(&self,instance:&GuestInstance)->Result<bool,OriginalTurnFailure>{let(Self::Owned(_),GuestInstanceState::Owned(state))=(self,&instance.state)else{return Err(unsupported())};Ok(state.original_unit_is_pending())}
}
